queries.query:
SELECT ?p ?pLabel ?v ?vLabel WHERE {
  wd:Q12616 ?pd ?v .
  ?p wikibase:directClaim ?pd .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?en ?sv ?mul ?ordinal ?effective ?proposed ?citation WHERE {
  ?item wdt:P31 wd:Q102410240 .
  OPTIONAL { ?item p:P179 ?s . ?s ps:P179 wd:Q230698 . OPTIONAL { ?s pq:P1545 ?ordinal } }
  OPTIONAL { ?item wdt:P7588 ?effective }
  OPTIONAL { ?item wdt:P1031 ?citation FILTER(STRSTARTS(?citation, "U.S. Const. am")) }
  OPTIONAL { ?item rdfs:label ?en FILTER(LANG(?en) = "en") }
  OPTIONAL { ?item rdfs:label ?sv FILTER(LANG(?sv) = "sv") }
  OPTIONAL { ?item rdfs:label ?mul FILTER(LANG(?mul) = "mul") }
}
ORDER BY ?effective

SELECT ?item ?ordinal ?kind ?lang ?text WHERE {
  ?item wdt:P31 wd:Q102410240 ; p:P179 ?s .
  ?s ps:P179 wd:Q230698 ; pq:P1545 ?ordinal .
  { ?item rdfs:label ?text . BIND("label" AS ?kind) }
  UNION { ?item skos:altLabel ?text . BIND("alias" AS ?kind) }
  BIND(LANG(?text) AS ?lang)
  FILTER(?lang IN ("en", "sv", "mul"))
}
ORDER BY xsd:integer(?ordinal) ?lang ?kind

